        body: `陰イオンの中でもっとも書き誤りが多いのが水酸化物イオンである。

■ 正しい書き方は OH−
酸素1個と水素1個がひとかたまりになり、全体として電子を1個多くもっている。だから−1価であり、OH− と書く。

■ よくある誤り
・OH２− と書く……酸素が2価だからと考えて、価数を2にしてしまう誤り。OH のかたまりは全体で−1価である。
・O２− と H＋ が別々にあると考える……水酸化ナトリウム水溶液の中にあるのは Na＋ と OH− であって、O２− や H＋ ではない。むしろ H＋ が存在しないことがアルカリ性の特徴である。
・OH− を「水酸イオン」と書く……正しくは水酸化物イオン。

■ 電離のようす（次で詳しく学ぶ）
水酸化ナトリウム NaOH → Na＋ ＋ OH−
水酸化カルシウム Ca(OH)２ → Ca２＋ ＋ 2OH−
水酸化バリウム Ba(OH)２ → Ba２＋ ＋ 2OH−

Ca(OH)２ で OH のまわりにかっこがついているのは、「OH というかたまりが2組ある」という意味である。だから電離すると 2OH− となる。ここを OH２− としてしまうと、まったくちがう粒子を表すことになる。

例）水酸化バリウム水溶液100cm３に OH− が20個分あるとすると、Ba２＋ は10個分である。＋2×10＝＋20 と −1×20＝−20 でつり合っている。

⚠ 注意：多原子イオンは「一つの粒」として扱う。SO４２− は硫黄と酸素に分かれて動くのではなく、SO４ のかたまりのまま水の中を移動する。`,
