        body: `電源・導線・水溶液をつないだ回路では、電流を運ぶ役目が場所によって入れかわっている。

■ 金属の導線の中
金属の原子は電子を手放しやすく、金属の中には特定の原子に属さない電子（自由電子）がたくさんある。この電子が電源の−極側から＋極側へ向かって移動することで、電流が流れる。電流の向きは電子の移動の向きと逆と決められている。

■ 水溶液の中
水溶液の中に自由電子はない。かわりに電離してできたイオンが移動する。
・陽イオン（Na＋、Cu２＋、H＋ など）→ −の電極すなわち陰極へ引かれる
・陰イオン（Cl−、OH−、SO４２− など）→ ＋の電極すなわち陽極へ引かれる

＋のものが一方向へ、−のものが反対方向へ動くので、どちらも同じ向きの電流に寄与している。

■ 境目では
電極の表面で、イオンと電極のあいだに電子の受け渡しが起こる。陰極では陽イオンが電子を受け取り、陽極では陰イオンが電子を渡す。こうしてバトンが電子からイオンへ、またイオンから電子へと渡り、回路全体がつながる。

★ ポイント：「水溶液の中を電子が流れている」と書くと誤り。水溶液の中を動くのはイオンである。電子が動くのは金属の部分だけ。この一線をはっきりさせておくと、電気分解も電池も同じ道具で説明できる。`,
