        body: `電気分解の問題でつまずく原因のほとんどは、極の名前と向きの混乱である。ここを一度で整理する。

■ 極の名前の決め方
・陰極……電源の−極につないだ電極
・陽極……電源の＋極につないだ電極
名前は「つないだ電源の極」で決まる。電極そのものの材質や形とは関係ない。

■ 電子の流れ
電子は−の電気をもつので、電源の−極から押し出され、導線を通って陰極へ流れこむ。そして陽極から電子が引き抜かれ、導線を通って電源の＋極へ戻る。

■ そこで起こること
・陰極……電子があふれている → 電子をほしがっている陽イオンが引きよせられ、電子を受け取る
・陽極……電子が足りない → 電子をもっている陰イオンが引きよせられ、電子を渡す

■ 向きのまとめ
陽イオン → 陰極へ移動 → 電子を受け取る
陰イオン → 陽極へ移動 → 電子を渡す

「陽イオンが陽極へ行く」と思ってしまいがちだが、これは逆である。＋のイオンは−の電極に引かれる、と電気の性質から考えれば必ず正しくなる。

★ ポイント：覚え方は「＋と−は引き合う」の一言でよい。陽イオン（＋）は陰極（−側）へ、陰イオン（−）は陽極（＋側）へ。名前ではなく符号で考える。`,
