        heading: '電極で起こる反応の書き方',
        body: `電極での反応は、電子を e− と書いて式に表す。この形に慣れておくと、電池の単元がそのまま解けるようになる。

■ 陰極（電子を受け取る側）
2H＋ ＋ 2e− → H２　　（水素イオンが水素になる）
Cu２＋ ＋ 2e− → Cu　　（銅イオンが銅になる）
Ag＋ ＋ e− → Ag　　　（銀イオンが銀になる）

電子は左辺に書く。「電子をもらう」からである。受け取る電子の数は、イオンの価数と一致する。

■ 陽極（電子を渡す側）
2Cl− → Cl２ ＋ 2e−　　（塩化物イオンが塩素になる）
4OH− → 2H２O ＋ O２ ＋ 4e−　（水酸化物イオンが酸素になる）

電子は右辺に書く。「電子を放す」からである。

■ 電子の数はつじつまが合う
回路は一つにつながっているので、陰極が受け取った電子の数と、陽極が放した電子の数は必ず等しくなる。

例）塩化銅の電気分解で、陰極で銅原子1個ができるとき電子2個が使われる。陽極ではその同じ2個が放されるので、Cl− が2個反応して塩素分子 Cl２ が1個できる。つまり銅1個に対して塩素分子1個の割合になり、CuCl２ → Cu ＋ Cl２ という関係と一致する。

⚠ 注意：陰極を「−極」、陽極を「＋極」と書くのは電気分解では避けたほうがよい。次に学ぶ電池では＋極・−極という別の呼び方を使い、電子の流れる向きが逆になるからである。電気分解は陰極・陽極、電池は＋極・−極と呼び分ける。`,
