        body: `硫酸銅水溶液（青色）に亜鉛板を入れると、次の変化が観察される。

■ 観察されること
・亜鉛板の表面に赤色（赤褐色）の物質が付着する → 銅である。
・亜鉛板がやせて細くなる → 亜鉛がとけている。
・水溶液の青色がうすくなる → Cu２＋ が減っている。
・液の温度が上がる → 発熱反応である。

■ 起きていること
亜鉛は銅よりイオンになりやすい。そのため亜鉛が電子を手放してイオンになり、その電子を水溶液中の銅イオンが受け取って金属の銅になる。
Zn → Zn２＋ ＋ 2e−（亜鉛がとける）
Cu２＋ ＋ 2e− → Cu（銅が出てくる）
合わせて Zn ＋ Cu２＋ → Zn２＋ ＋ Cu

■ 逆はどうか
銅板を硫酸亜鉛水溶液に入れても、何も起こらない。銅は亜鉛よりイオンになりにくいので、銅がとけて Zn２＋ に電子を渡すという反応は起こらない。

■ この「起こる／起こらない」で順位が決まる
Aの金属をBのイオンの水溶液に入れて反応が起これば、A のほうがイオンになりやすい。この実験を組み合わせれば、金属の順位を実験だけで決められる。

★ ポイント：観察の記述は三点セットで書く。「入れた金属がとける」「水溶液中の金属が出てくる」「水溶液の色がうすくなる（色のある場合）」。この三つが同時に起こる。`,
