        body: `金属がイオンになりやすいということは、まわりの酸素や水と反応しやすいということでもある。

■ さびやすさの順
マグネシウム ＞ 亜鉛 ＞ 鉄 ＞ 銅 ＞ 銀
左ほどさびやすい。金はほとんどさびず、古代の装飾品が今も輝いたまま残っている。

■ さびを防ぐ方法
①塗装する……空気や水とふれさせない。橋や鉄塔。
②油をぬる……工具や刃物。
③さびにくい金属でおおう……めっき。
④さびにくい合金にする……ステンレス鋼（鉄にクロムとニッケルを加えたもの）。
⑤酸化物の膜であらかじめおおう……アルミサッシの表面処理（アルマイト）。

■ トタンとブリキのちがい（頻出）
・トタン……鉄の表面を亜鉛でおおったもの。亜鉛は鉄よりイオンになりやすいので、傷がついて鉄が露出しても、まず亜鉛のほうがとける。鉄はしばらく守られる。屋根や外壁など、傷がつきやすい場所に使う。
・ブリキ……鉄の表面をスズでおおったもの。スズは鉄よりイオンになりにくい。傷がなければ美しく保てるが、傷がつくと露出した鉄のほうが先にとけ、内部からさびが進む。かんづめの缶や玩具など、傷がつきにくい用途に使う。

★ ポイント：トタンとブリキは「どちらがイオンになりやすいか」だけで説明できる。守る側の金属がイオンになりやすいのがトタン、なりにくいのがブリキ。名前を覚えるより、性質から導けるようにしておく。`,
