        body: `うすい塩酸に、亜鉛板と銅板を入れて導線でつなぐと、電流が流れて豆電球がつく。これがもっとも簡単な化学電池である。

■ 必要な三つの条件
①種類のちがう二枚の金属板を使う
②電解質の水溶液に入れる
③二枚の金属板を導線でつなぐ

このうち一つでも欠けると電流は流れない。
・同じ金属を二枚使う → イオンへのなりやすさに差がないので、電子が流れる理由がない。
・砂糖水（非電解質）を使う → イオンがないので、水溶液の中で電気を運べない。
・導線でつながない → 回路が閉じないので電子が移動できない。

■ どちらが−極になるか
イオンになりやすいほうの金属が、電子を放してとけ出す。放された電子はその金属板に残るので、その金属板は電子が余っている状態になる。電子が余っている極が−極である。

亜鉛と銅なら、亜鉛のほうがイオンになりやすいので、亜鉛板が−極、銅板が＋極になる。

■ それぞれの極で起こること
−極（亜鉛板）：Zn → Zn２＋ ＋ 2e−　亜鉛がとけて細くなる
＋極（銅板）：2H＋ ＋ 2e− → H２　水素の泡が出る

■ 電子と電流の向き
電子：−極（亜鉛板）→ 導線 → ＋極（銅板）
電流：＋極（銅板）→ 導線 → −極（亜鉛板）
向きが逆であることに注意する。

★ ポイント：「とけるほうが−極」と覚えると、極の判定でまず迷わない。イオンになりやすい＝電子を出す＝−極、と一直線に結びつける。`,
