        heading: 'ダニエル電池の構造と反応',
        body: `ダニエル電池は、二つの水溶液を分けたところに特徴がある。

■ 構造
・−極側……硫酸亜鉛水溶液（ZnSO４ 水溶液）に亜鉛板を入れる
・＋極側……硫酸銅水溶液（CuSO４ 水溶液）に銅板を入れる
・二つの水溶液のあいだをセロハン（または素焼きの板）で仕切る
・亜鉛板と銅板を導線でつなぐ

■ −極（亜鉛板）
Zn → Zn２＋ ＋ 2e−
亜鉛がとけてイオンになり、電子を亜鉛板に残す。亜鉛板は表面がぼろぼろになり、質量が減る。硫酸亜鉛水溶液の中では Zn２＋ が増える。

■ ＋極（銅板）
Cu２＋ ＋ 2e− → Cu
導線を通ってきた電子を、水溶液中の銅イオンが受け取り、銅となって銅板に付着する。銅板の質量は増える。硫酸銅水溶液の中では Cu２＋ が減るので、青色がうすくなる。

■ 全体
Zn ＋ Cu２＋ → Zn２＋ ＋ Cu
これは、硫酸銅水溶液に亜鉛板を直接入れたときの反応とまったく同じである。ちがうのは、直接入れた場合は熱として出てしまうエネルギーを、電池では電気として取り出せる点である。

★ ポイント：ダニエル電池の四つの変化をセットで覚える。「亜鉛板は減る」「銅板は増える」「亜鉛イオンは増える」「銅イオンは減って青色がうすくなる」。`,
