        body: `この単元の失点でもっとも多いのが、電子と電流の向きの取りちがえである。

■ 二つの向き
電子の向き：−極 → 導線 → ＋極
電流の向き：＋極 → 導線 → −極

■ なぜ逆なのか
電流の向きは、電子が発見されるより前に「＋の電気が移動する向き」として決められた。あとになって、実際に動いているのは−の電気をもつ電子だとわかったが、決まりはそのまま使われている。そのため、電子の移動の向きと電流の向きは逆になる。

■ 電気分解との比較
電気分解……電源の−極 → 陰極 へ電子が流れこむ
電池……電池の−極 → 導線 → ＋極 へ電子が流れ出る

電池の−極は「電子を送り出す側」、電気分解の陰極は「電子を受け取る側」である。名前の似ている「−極」と「陰極」を同じものと考えないよう、必ず装置ごとに整理する。

■ 電池の中と外
・電池の外（導線）……電子が−極から＋極へ移動する
・電池の中（水溶液）……イオンが移動する。陽イオンが＋極側へ、陰イオンが−極側へ動くことで回路が閉じる
電池の中でも電子が流れていると考えると誤りになる。

例）亜鉛板と銅板をうすい塩酸に入れた電池では、水溶液中の H＋ が銅板（＋極）へ引かれて移動し、そこで電子を受け取って水素になる。水溶液の中を動いているのはイオンである。

■ まとめの図式
とけるほう＝イオンになりやすいほう＝電子を出すほう＝−極
　　↓（導線を電子が流れる）
とけないほう＝イオンになりにくいほう＝電子を受け取るほう＝＋極

⚠ 注意：「−極から電流が流れ出る」と書くのは誤り。流れ出るのは電子であり、電流は＋極から流れ出るものとして定義されている。答案では「電子」と「電流」の語を厳密に使い分ける。`,
