        heading: '身のまわりの電池と使い分け',
        body: `どの電池を使うかは、必要な電圧・電流・重さ・寿命で決まる。

■ 乾電池のしくみ（簡単に）
マンガン乾電池では、亜鉛が−極、二酸化マンガンと炭素棒が＋極側ではたらく。電解質には塩化亜鉛などを使い、こぼれないようにのり状にしてある。「乾」電池というのは、水溶液がこぼれない形にしてあるという意味で、水がまったくないわけではない。

■ 直列と並列
・直列につなぐと電圧が加わる。1.5Vの乾電池2個で3V。
・並列につなぐと電圧は変わらないが、長持ちする。

■ 電池の寿命
電池が使えなくなるのは、電気を「使い果たした」からではなく、電池の中で反応する物質がなくなったからである。電池は電気の貯蔵庫ではなく、化学変化を電気に変える装置だという見方をここでも使う。

■ 環境への配慮
・使い終わった電池は決められた方法で回収する。中に含まれる金属を再利用でき、有害な物質が環境に出るのも防げる。
・ボタン電池は小さな子どもが飲みこむ事故が多いので、保管に注意する。

例）電気自動車が普及するかどうかは、電池の性能（1回の充電で走れる距離、充電にかかる時間、寿命、価格）に大きく左右される。リチウムイオン電池の改良が続けられているのはこのためである。

⚠ 注意：電池の＋極と−極を導線で直接つなぐ（ショートさせる）と、非常に大きな電流が流れて発熱し危険である。実験では必ず豆電球やモーターなどの抵抗をはさむ。`,
