        body: `塩は、酸の陰イオンとアルカリの陽イオンを組み合わせてつくる。ここでも「＋と−をつり合わせる」という考え方だけで書ける。

■ 手順
①酸の陰イオンを取り出す（塩酸→Cl−、硫酸→SO４２−、硝酸→NO３−）
②アルカリの陽イオンを取り出す（NaOH→Na＋、Ca(OH)２→Ca２＋、Ba(OH)２→Ba２＋）
③＋と−がつり合う個数で組み合わせる

■ 主な組み合わせ
塩酸 ＋ 水酸化ナトリウム → 塩化ナトリウム NaCl ＋ 水
　HCl ＋ NaOH → NaCl ＋ H２O
硫酸 ＋ 水酸化ナトリウム → 硫酸ナトリウム Na２SO４ ＋ 水
　H２SO４ ＋ 2NaOH → Na２SO４ ＋ 2H２O
硝酸 ＋ 水酸化ナトリウム → 硝酸ナトリウム NaNO３ ＋ 水
　HNO３ ＋ NaOH → NaNO３ ＋ H２O
塩酸 ＋ 水酸化カルシウム → 塩化カルシウム CaCl２ ＋ 水
　2HCl ＋ Ca(OH)２ → CaCl２ ＋ 2H２O
硫酸 ＋ 水酸化バリウム → 硫酸バリウム BaSO４ ＋ 水
　H２SO４ ＋ Ba(OH)２ → BaSO４ ＋ 2H２O

★ ポイント：化学反応式の係数は、あとから水の数で調整する。たとえば H２SO４ と NaOH の反応では、H＋ が2個あるので OH− も2個必要 → NaOH が2つ、水も2つ、と決まる。「H＋ の数に合わせる」と考えれば係数で迷わない。`,
