        heading: '身のまわりの中和',
        body: `中和は、生活や産業のさまざまな場面で使われている。

■ 胃薬
胃液には塩酸が含まれていて、pH は1〜2 の強い酸性である。食べ物の消化とともに殺菌の役目もしているが、出すぎると胃が荒れる。そこで、炭酸水素ナトリウム（重そう）や水酸化マグネシウムなどのアルカリ性の成分で中和する。

■ 酸性の土壌の改良
日本は雨が多く、土から養分が流されやすいため、土壌が酸性にかたよりがちである。多くの作物は弱い酸性から中性の土を好むので、消石灰（水酸化カルシウム）や石灰石の粉をまいて中和する。まきすぎるとアルカリ性にかたよるので、pH を測りながら調整する。

■ 虫さされ
一部の虫の出す液は酸性なので、アルカリ性の薬（アンモニア水など）で中和する。ただし虫の種類によって成分がちがい、必ずしも酸性とは限らない。

■ 排煙処理
石炭や石油を燃やすと、含まれていた硫黄が二酸化硫黄になって出る。これは水にとけると酸性になり、酸性雨の原因になる。そこで排煙に石灰乳（水酸化カルシウムの懸濁液）をふきつけて中和し、硫酸カルシウムとして取り除く。これを排煙脱硫という。

■ 湖沼の中和
酸性雨で酸性になりすぎた湖に石灰をまいて pH を戻す取り組みもある。ただし対症療法であり、根本の解決には排出そのものを減らす必要がある。

■ 生活の中の例
・魚を焼くときにレモンをしぼる……生ぐささのもとになるアルカリ性の成分を酸で中和する。
・洗剤のあとに酢を使う……アルカリ性の残りを中和する。
・パイプ洗浄剤（アルカリ性）と酸性の洗剤は混ぜてはいけない……中和で急に発熱したり、種類によっては有毒な気体が出たりする。

⚠ 注意：「混ぜるな危険」の表示は、塩素系（次亜塩素酸ナトリウム）と酸性タイプを混ぜると有毒な塩素が発生するためである。これは中和そのものの危険というより、生じる気体の危険である。理由を区別して覚えておく。`,
