        heading: '沈殿の量とイオンの数のグラフ',
        body: `同じ実験で、別の量を測るとグラフの形が変わる。何を測っているのかを必ず確認する。

■ 沈殿（硫酸バリウム）の質量
・中和点まで……加えた水酸化バリウムの量に比例して増える（右上がりの直線）
・中和点から先……SO４２− がもうないので、これ以上沈殿はできない（水平）
→ 中和点で折れ曲がって水平になる形。

■ 各イオンの数
硫酸イオン SO４２−：はじめが最大、加えるにつれて減り、中和点で0。以後0のまま。
水素イオン H＋：はじめが最大、減って中和点で0。以後0のまま。
バリウムイオン Ba２＋：中和点まで0（加えたそばから沈殿になる）。中和点をこえてから増える。
水酸化物イオン OH−：中和点まで0（加えたそばから水になる）。中和点をこえてから増える。

塩酸＋水酸化ナトリウムの場合と比べると、Na＋ が「はじめから増え続けた」のに対し、Ba２＋ は「中和点まで0」という点が決定的にちがう。Na＋ は水にとけたまま残るが、Ba２＋ は沈殿になって水溶液から消えるからである。

■ 質量の保存
沈殿ができても、容器全体の質量は変わらない。水溶液の中でイオンだったものが固体になっただけで、外へ出ていったものはないからである（気体が発生する反応とはちがう）。

例）ビーカーごと電子てんびんにのせて、硫酸に水酸化バリウム水溶液を加えていく。白い沈殿が生じても、加えた水溶液の質量の分だけ増えるだけで、それ以外の増減はない。

■ グラフ問題の解き方
①横軸・縦軸が何かを読む（加えた体積か、時間か。電流か、沈殿の質量か、イオンの数か）
②中和点がどこかを、いずれかのグラフの折れ点から特定する
③「消えるもの」「残るもの」「増えるもの」を仕分ける

⚠ 注意：「電流が0になった＝反応が終わった」ではない。電流が0になったのは中和点であって、そこからさらに水酸化バリウム水溶液を加えれば、水溶液はアルカリ性になり電流も流れる。0はグラフの最小点であって終点ではない。`,
