        heading: '総合演習',
        body: `実際の出題の形で確認する。設定は次のとおりとする。

【設定】うすい塩酸20cm３に、同じ濃さの水酸化ナトリウム水溶液を少しずつ加える。20cm３加えたときにちょうど中和した。

■ 問1：10cm３加えた時点の水溶液は何性か。BTB液の色は。
中和点の半分なので、H＋ がまだ半分残っている → 酸性 → 黄色。

■ 問2：10cm３加えた時点で、水溶液中にもっとも多いイオンは何か。
はじめの H＋ を20個分とすると、10cm３加えた時点では
H＋ 10個分、Na＋ 10個分、Cl− 20個分、OH− 0個分
もっとも多いのは Cl− である。

■ 問3：30cm３加えた時点で存在するイオンをすべて答えよ。
H＋ 0個分、OH− 10個分、Na＋ 30個分、Cl− 20個分
存在するのは Na＋、Cl−、OH− の三種類。

■ 問4：30cm３加えた水溶液を中性にするには、この塩酸をあと何cm３加えればよいか。
余っている OH− は10個分。これを中和するには H＋ が10個分必要。塩酸20cm３に H＋ が20個分だから、10個分は塩酸10cm３にあたる。よって10cm３。

■ 問5：この塩酸20cm３に水を加えて全体を100cm３にしたものを中和するには、水酸化ナトリウム水溶液は何cm３必要か。
水を加えても H＋ の数は変わらないので、20cm３のまま。

■ 問6：もとの塩酸20cm３に、濃さが2倍の水酸化ナトリウム水溶液を加える場合、ちょうど中和するのは何cm３か。
濃さが2倍なら同じ体積で OH− は2倍。したがって必要な体積は半分の10cm３。

⚠ 注意：問4のように「今の状態から中性にするには」と問われたら、余っている側の量をまず求める。はじめの量から計算し直そうとすると混乱する。「今どれだけ余っているか」→「それを消すのに何が何cm３必要か」の二段階で考える。`,
